1	import React, { useCallback, useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';
11	type Project = {
12	  id: number;
13	  name: string;
14	  clientId: number;
15	  clientName: string;
16	  archived: boolean;
17	  status: ProjectStatus;
18	};
19	type Invoice = {
20	  id: number;
21	  projectId: number;
22	  amount: number;
23	  amountDue: number;
24	  status: string;
25	  issuedDate: string;
26	  dueDate: string;
27	  discountPct: number;
28	  taxPct: number;
29	};
30	type Task = { id: number; projectId: number; title: string; done: boolean };
31	type Tag = { id: number; name: string };
32	type Note = { id: number; targetType: string; targetId: number; text: string; at: string };
33	
34	type LineItem = {
35	  id: number;
36	  invoiceId: number;
37	  description: string;
38	  qty: number;
39	  unit: string;
40	  unitPrice: number;
41	};
42	
43	type Payment = { id: number; invoiceId: number; amount: number; date: string };
44	
45	function money(amount: number): string {
46	  return `$${Number(amount).toLocaleString('en-US', {
47	    minimumFractionDigits: 2,
48	    maximumFractionDigits: 2,
49	  })}`;
50	}
51	
52	// Budget figures are shown with thousands separators (e.g. $1,000.00) so larger amounts stay
53	// readable at a glance.
54	function moneyGrouped(amount: number): string {
55	  return `$${Number(amount).toLocaleString('en-US', {
56	    minimumFractionDigits: 2,
57	    maximumFractionDigits: 2,
58	  })}`;
59	}
60	
61	type ProjectBudget = { budget: number | null; invoiced: number; remaining: number | null };
62	
63	// Load a JSON resource from `url` into state, refetching whenever the url changes, and hand back a
64	// `reload` for callers that mutate the resource and need to pull the fresh version. Every project
65	// panel reads one url this way, so this is where that fetch-into-state pattern lives once.
66	function useJsonResource<T>(url: string, initial: T): [T, () => Promise<void>] {
67	  const [data, setData] = useState<T>(initial);
68	  const reload = useCallback(async () => {
69	    const res = await fetch(url);
70	    setData(await res.json());
71	  }, [url]);
72	  useEffect(() => {
73	    void reload();
74	  }, [reload]);
75	  return [data, reload];
76	}
77	
78	// One charge line while it is being edited on screen: the fields are held as raw strings so the
79	// inputs stay controlled and the total can recompute live as they change.
80	type EditItem = { id: number; description: string; qty: string; unit: string; unitPrice: string };
81	
82	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
83	// many, price each), the total worked out for you, and a form to add another line. Each line can be
84	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
85	// own line-item state, scoped to the one invoice it is showing.
86	function InvoiceDetail({
87	  invoiceId,
88	  onChange,
89	  onClose,
90	}: {
91	  invoiceId: number;
92	  onChange: () => void;
93	  onClose: () => void;
94	}) {
95	  const [items, setItems] = useState<EditItem[]>([]);
96	  const [description, setDescription] = useState('');
97	  const [qty, setQty] = useState('');
98	  const [unit, setUnit] = useState('');
99	  const [unitPrice, setUnitPrice] = useState('');
100	  const [payments, setPayments] = useState<Payment[]>([]);
101	  const [paymentAmount, setPaymentAmount] = useState('');
102	  const [paymentDate, setPaymentDate] = useState('');
103	  const [status, setStatus] = useState('');
104	  // The percentage discount taken off this invoice's subtotal (0 unless one is set).
105	  const [discountPct, setDiscountPct] = useState(0);
106	  // The percentage sales tax added on top after the discount (0 unless one is set).
107	  const [taxPct, setTaxPct] = useState(0);
108	
109	  // The status is worked out from the payments recorded against the invoice, so re-read it whenever
110	  // a payment is added rather than flipping it by hand. The discount and tax percentages come back
111	  // on the same read.
112	  async function loadStatus() {
113	    const res = await fetch(`/api/invoices/${invoiceId}`);
114	    const inv: Invoice = await res.json();
115	    setStatus(inv.status);
116	    setDiscountPct(Number(inv.discountPct) || 0);
117	    setTaxPct(Number(inv.taxPct) || 0);
118	  }
119	
120	  async function load() {
121	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
122	    const rows: LineItem[] = await res.json();
123	    setItems(
124	      rows.map((li) => ({
125	        id: li.id,
126	        description: li.description,
127	        qty: String(li.qty),
128	        unit: li.unit,
129	        unitPrice: String(li.unitPrice),
130	      })),
131	    );
132	  }
133	
134	  async function loadPayments() {
135	    const res = await fetch(`/api/invoices/${invoiceId}/payments`);
136	    setPayments(await res.json());
137	  }
138	
139	  async function submitPayment(e: React.FormEvent) {
140	    e.preventDefault();
141	    const value = Number(paymentAmount);
142	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
143	      return;
144	    }
145	    if (paymentDate.trim() === '') {
146	      return;
147	    }
148	    await fetch(`/api/invoices/${invoiceId}/payments`, {
149	      method: 'POST',
150	      headers: { 'Content-Type': 'application/json' },
151	      body: JSON.stringify({ amount: value, date: paymentDate }),
152	    });
153	    setPaymentAmount('');
154	    setPaymentDate('');
155	    await loadPayments();
156	    await loadStatus();
157	    onChange();
158	  }
159	
160	  useEffect(() => {
161	    void load();
162	    void loadPayments();
163	    void loadStatus();
164	  }, [invoiceId]);
165	
166	  function editField(
167	    id: number,
168	    field: 'description' | 'qty' | 'unit' | 'unitPrice',
169	    value: string,
170	  ) {
171	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
172	  }
173	
174	  function amountOf(li: EditItem): number {
175	    const line = Number(li.qty) * Number(li.unitPrice);
176	    return Number.isFinite(line) ? line : 0;
177	  }
178	
179	  async function save(li: EditItem) {
180	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
181	      return;
182	    }
183	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
184	      method: 'POST',
185	      headers: { 'Content-Type': 'application/json' },
186	      body: JSON.stringify({
187	        description: li.description,
188	        qty: Number(li.qty),
189	        unit: li.unit,
190	        unitPrice: Number(li.unitPrice),
191	      }),
192	    });
193	    await load();
194	    onChange();
195	  }
196	
197	  async function remove(id: number) {
198	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
199	    await load();
200	    onChange();
201	  }
202	
203	  async function submit(e: React.FormEvent) {
204	    e.preventDefault();
205	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
206	      return;
207	    }
208	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
209	      method: 'POST',
210	      headers: { 'Content-Type': 'application/json' },
211	      body: JSON.stringify({
212	        description,
213	        qty: Number(qty),
214	        unit,
215	        unitPrice: Number(unitPrice),
216	      }),
217	    });
218	    setDescription('');
219	    setQty('');
220	    setUnit('');
221	    setUnitPrice('');
222	    await load();
223	    onChange();
224	  }
225	
226	  // The subtotal is the sum of the line items; the discount is that percentage taken off it. Sales
227	  // tax is then added on top of the discounted base (worked out after the discount), and the final
228	  // total is the subtotal less the discount plus that tax.
229	  const subtotal = items.reduce((sum, li) => sum + amountOf(li), 0);
230	  const discount = (subtotal * discountPct) / 100;
231	  const tax = ((subtotal - discount) * taxPct) / 100;
232	  const total = subtotal - discount + tax;
233	
234	  return (
235	    <section data-testid="invoice-detail">
236	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
237	        Back to invoices
238	      </button>
239	
240	      <p data-testid="invoice-status">{status}</p>
241	
242	      <table data-testid="invoice-lineitems-table">
243	        <tbody>
244	          {items.map((li) => (
245	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
246	              <td>
247	                <input
248	                  data-testid="lineitem-description"
249	                  value={li.description}
250	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
251	                />
252	              </td>
253	              <td data-testid="lineitem-qty">{li.qty}</td>
254	              <td data-testid="lineitem-unit">{li.unit}</td>
255	              <td>
256	                <input
257	                  data-testid="lineitem-unitprice"
258	                  value={li.unitPrice}
259	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
260	                />
261	              </td>
262	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
263	              <td>
264	                <button
265	                  data-testid={`lineitem-save-${li.id}`}
266	                  type="button"
267	                  onClick={() => save(li)}
268	                >
269	                  Save
270	                </button>
271	                <button
272	                  data-testid={`lineitem-remove-${li.id}`}
273	                  type="button"
274	                  onClick={() => remove(li.id)}
275	                >
276	                  Remove
277	                </button>
278	              </td>
279	            </tr>
280	          ))}
281	        </tbody>
282	      </table>
283	
284	      <p data-testid="invoice-subtotal">{money(subtotal)}</p>
285	      <p data-testid="invoice-discount">{money(discount)}</p>
286	      <p data-testid="invoice-tax">{money(tax)}</p>
287	      <p data-testid="invoice-amount">{money(total)}</p>
288	
289	      <form data-testid="lineitem-form" onSubmit={submit}>
290	        <input
291	          data-testid="lineitem-form-description"
292	          placeholder="Description"
293	          value={description}
294	          onChange={(e) => setDescription(e.target.value)}
295	        />
296	        <input
297	          data-testid="lineitem-form-qty"
298	          placeholder="How many"
299	          value={qty}
300	          onChange={(e) => setQty(e.target.value)}
301	        />
302	        <input
303	          data-testid="lineitem-form-unit"
304	          placeholder="Unit"
305	          value={unit}
306	          onChange={(e) => setUnit(e.target.value)}
307	        />
308	        <input
309	          data-testid="lineitem-form-unitprice"
310	          placeholder="Price each"
311	          value={unitPrice}
312	          onChange={(e) => setUnitPrice(e.target.value)}
313	        />
314	        <button data-testid="lineitem-form-submit" type="submit">
315	          Add line item
316	        </button>
317	      </form>
318	
319	      <table data-testid="invoice-payments-table">
320	        <tbody>
321	          {payments.map((p) => (
322	            <tr key={p.id} data-testid={`payment-row-${p.id}`}>
323	              <td data-testid="payment-amount">{money(p.amount)}</td>
324	              <td data-testid="payment-date">{p.date}</td>
325	            </tr>
326	          ))}
327	        </tbody>
328	      </table>
329	
330	      <form data-testid="payment-form" onSubmit={submitPayment}>
331	        <input
332	          data-testid="payment-form-amount"
333	          placeholder="Amount paid"
334	          value={paymentAmount}
335	          onChange={(e) => setPaymentAmount(e.target.value)}
336	        />
337	        <input
338	          data-testid="payment-form-date"
339	          type="date"
340	          value={paymentDate}
341	          onChange={(e) => setPaymentDate(e.target.value)}
342	        />
343	        <button data-testid="payment-form-submit" type="submit">
344	          Record payment
345	        </button>
346	      </form>
347	    </section>
348	  );
349	}
350	
351	// Which lifecycle actions an invoice offers depends on where it is in its lifecycle: a draft can be
352	// sent, a sent invoice can be marked paid. Collecting the mapping here keeps the row markup flat and
353	// gives one obvious place to add a new lifecycle action.
354	function InvoiceActions({
355	  invoice,
356	  onOpen,
357	  onSend,
358	  onPay,
359	  onCancel,
360	}: {
361	  invoice: Invoice;
362	  onOpen: () => void;
363	  onSend: () => void;
364	  onPay: () => void;
365	  onCancel: () => void;
366	}) {
367	  return (
368	    <>
369	      <button data-testid={`invoice-open-${invoice.id}`} onClick={onOpen}>
370	        Open
371	      </button>
372	      {invoice.status === 'DRAFT' && (
373	        <button data-testid={`invoice-send-${invoice.id}`} onClick={onSend}>
374	          Send
375	        </button>
376	      )}
377	      {invoice.status === 'SENT' && (
378	        <button data-testid={`invoice-pay-${invoice.id}`} onClick={onPay}>
379	          Mark paid
380	        </button>
381	      )}
382	      {invoice.status === 'SENT' && (
383	        <button data-testid={`invoice-cancel-${invoice.id}`} onClick={onCancel}>
384	          Cancel
385	        </button>
386	      )}
387	    </>
388	  );
389	}
390	
391	// The invoices raised against a project: what they add up to, a form to raise another, and a drill-in
392	// to each invoice's line items and payments. Owns its own invoice state, scoped to the one project.
393	// Whenever the invoices change (a new one raised, a status moved, a line item edited) the owner is
394	// told so figures derived from them — the budget's invoiced/remaining — can be refreshed.
395	function ProjectInvoices({
396	  projectId,
397	  onInvoicesChanged,
398	}: {
399	  projectId: number;
400	  onInvoicesChanged: () => void;
401	}) {
402	  const [invoices, setInvoices] = useState<Invoice[]>([]);
403	  const [amount, setAmount] = useState('');
404	  const [amountError, setAmountError] = useState('');
405	  const [sortByDue, setSortByDue] = useState(false);
406	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
407	
408	  async function load() {
409	    const res = await fetch(`/api/invoices?projectId=${projectId}`);
410	    setInvoices(await res.json());
411	    onInvoicesChanged();
412	  }
413	
414	  useEffect(() => {
415	    void load();
416	  }, [projectId]);
417	
418	  async function submit(e: React.FormEvent) {
419	    e.preventDefault();
420	    const value = Number(amount);
421	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
422	      setAmountError('Amount must be more than zero');
423	      return;
424	    }
425	    setAmountError('');
426	    await fetch('/api/invoices', {
427	      method: 'POST',
428	      headers: { 'Content-Type': 'application/json' },
429	      body: JSON.stringify({ projectId, amount: value }),
430	    });
431	    setAmount('');
432	    await load();
433	  }
434	
435	  // A lifecycle move (send, mark paid, …) is a POST to the matching action route followed by a reload;
436	  // routing them through one place means a new action is one more call site, not new plumbing.
437	  async function transition(id: number, action: 'send' | 'pay' | 'cancel') {
438	    await fetch(`/api/invoices/${id}/${action}`, { method: 'POST' });
439	    await load();
440	  }
441	
442	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
443	  const shownInvoices = sortByDue
444	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
445	    : invoices;
446	
447	  return (
448	    <>
449	      <form data-testid="invoice-form" onSubmit={submit}>
450	        <input
451	          data-testid="invoice-form-amount"
452	          placeholder="Amount"
453	          value={amount}
454	          onChange={(e) => setAmount(e.target.value)}
455	        />
456	        <button data-testid="invoice-form-submit" type="submit">
457	          Add invoice
458	        </button>
459	        {amountError && (
460	          <p data-testid="invoice-form-amount-error" role="alert">
461	            {amountError}
462	          </p>
463	        )}
464	      </form>
465	
466	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
467	        Sort by due date
468	      </button>
469	
470	      {openInvoiceId === null ? (
471	        <>
472	          <table data-testid="project-invoices-table">
473	            <tbody>
474	              {shownInvoices.map((inv) => (
475	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
476	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
477	                  <td data-testid="invoice-due-amount">{money(inv.amountDue)}</td>
478	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
479	                  <td data-testid="invoice-due">{inv.dueDate}</td>
480	                  <td data-testid="invoice-status">{inv.status}</td>
481	                  <td>
482	                    <InvoiceActions
483	                      invoice={inv}
484	                      onOpen={() => setOpenInvoiceId(inv.id)}
485	                      onSend={() => transition(inv.id, 'send')}
486	                      onPay={() => transition(inv.id, 'pay')}
487	                      onCancel={() => transition(inv.id, 'cancel')}
488	                    />
489	                  </td>
490	                </tr>
491	              ))}
492	            </tbody>
493	          </table>
494	
495	          <p data-testid="project-invoices-total">{money(total)}</p>
496	        </>
497	      ) : (
498	        <InvoiceDetail
499	          invoiceId={openInvoiceId}
500	          onChange={load}
501	          onClose={() => setOpenInvoiceId(null)}
502	        />
503	      )}
504	    </>
505	  );
506	}
507	
508	// A project's budget: what was set for it, what has been invoiced against it so far, and what is
509	// left over. Invoiced (and so remaining) is derived from the project's invoices, so the owner bumps
510	// `reloadKey` whenever they change and this re-reads the budget picture. Owns its own budget state.
511	function BudgetPanel({ projectId, reloadKey }: { projectId: number; reloadKey: number }) {
512	  const [budget, setBudget] = useState<ProjectBudget | null>(null);
513	  const [budgetInput, setBudgetInput] = useState('');
514	
515	  async function load() {
516	    const res = await fetch(`/api/projects/${projectId}/budget`);
517	    setBudget(await res.json());
518	  }
519	
520	  useEffect(() => {
521	    void load();
522	  }, [projectId, reloadKey]);
523	
524	  async function submit(e: React.FormEvent) {
525	    e.preventDefault();
526	    const value = Number(budgetInput);
527	    if (budgetInput.trim() === '' || !Number.isFinite(value) || value < 0) {
528	      return;
529	    }
530	    await fetch(`/api/projects/${projectId}/budget`, {
531	      method: 'POST',
532	      headers: { 'Content-Type': 'application/json' },
533	      body: JSON.stringify({ budget: value }),
534	    });
535	    setBudgetInput('');
536	    await load();
537	  }
538	
539	  return (
540	    <section data-testid="project-budget-panel">
541	      <p data-testid="project-budget">
542	        {budget && budget.budget != null ? moneyGrouped(budget.budget) : ''}
543	      </p>
544	      <p data-testid="project-invoiced">{moneyGrouped(budget ? budget.invoiced : 0)}</p>
545	      <p data-testid="project-remaining">
546	        {budget && budget.remaining != null ? moneyGrouped(budget.remaining) : ''}
547	      </p>
548	      <form data-testid="project-budget-form" onSubmit={submit}>
549	        <input
550	          data-testid="project-budget-input"
551	          placeholder="Budget"
552	          value={budgetInput}
553	          onChange={(e) => setBudgetInput(e.target.value)}
554	        />
555	        <button data-testid="project-budget-submit" type="submit">
556	          Set budget
557	        </button>
558	      </form>
559	    </section>
560	  );
561	}
562	
563	// A project's labels: the ones on it now (each removable) and a picker of the remaining labels to add
564	// another. Owns its own tag state, scoped to the one project.
565	function TagsPanel({ projectId }: { projectId: number }) {
566	  const [tags, reloadTags] = useJsonResource<Tag[]>(`/api/projects/${projectId}/tags`, []);
567	  const [allTags, reloadAllTags] = useJsonResource<Tag[]>('/api/tags', []);
568	  const [tagToAdd, setTagToAdd] = useState('');
569	
570	  async function reload() {
571	    await Promise.all([reloadTags(), reloadAllTags()]);
572	  }
573	
574	  async function addTag(e: React.FormEvent) {
575	    e.preventDefault();
576	    if (!tagToAdd) {
577	      return;
578	    }
579	    await fetch(`/api/projects/${projectId}/tags`, {
580	      method: 'POST',
581	      headers: { 'Content-Type': 'application/json' },
582	      body: JSON.stringify({ tagId: Number(tagToAdd) }),
583	    });
584	    setTagToAdd('');
585	    await reload();
586	  }
587	
588	  async function removeTag(id: number) {
589	    await fetch(`/api/projects/${projectId}/tags/${id}/remove`, { method: 'POST' });
590	    await reload();
591	  }
592	
593	  return (
594	    <>
595	      <div data-testid="project-tags">
596	        {tags.map((tag) => (
597	          <span key={tag.id}>
598	            <span data-testid={`project-tag-${tag.id}`}>{tag.name}</span>
599	            <button
600	              data-testid={`project-tag-remove-${tag.id}`}
601	              type="button"
602	              onClick={() => removeTag(tag.id)}
603	            >
604	              Remove
605	            </button>
606	          </span>
607	        ))}
608	      </div>
609	
610	      <form data-testid="project-tag-form" onSubmit={addTag}>
611	        <select
612	          data-testid="project-tag-add"
613	          value={tagToAdd}
614	          onChange={(e) => setTagToAdd(e.target.value)}
