39	// Load a JSON resource from `url` into state, refetching whenever the url changes, and hand back a
40	// `reload` for callers that mutate the resource and need to pull the fresh version. Every client
41	// panel reads one url this way, so this is where that fetch-into-state pattern lives once.
42	function useJsonResource<T>(url: string, initial: T): [T, () => Promise<void>] {
