358	  // substring match on the client name; an empty box shows everyone.
359	  const [search, setSearch] = useState('');
360	  // How the list is ordered: by name (default) or by how much each client owes (most first).
361	  const [sort, setSort] = useState<SortKey>('name');
362	  const [openId, setOpenId] = useState<number | null>(null);
363	  // Which client (if any) is being corrected: opening the edit form seeds it with that client's
364	  // current name and email so the user tweaks rather than retypes.
365	  const [editingId, setEditingId] = useState<number | null>(null);
366	
367	  // Two clients cannot share an email; the server rejects a duplicate, so surface it and keep the
368	  // form as-is rather than clearing or reloading (nothing was added).
369	  async function addClient(values: { name: string; email: string }): Promise<string | null> {
370	    const res = await fetch('/api/clients', {
371	      method: 'POST',
372	      headers: { 'Content-Type': 'application/json' },
373	      body: JSON.stringify(values),
374	    });
375	    if (!res.ok) {
376	      return 'A client with this email already exists.';
377	    }
378	    await reload();
379	    return null;
380	  }
