      return;
    }
    const error = await onSubmit({ name, email });
    if (error) {
      setEmailError(error);
      return;
    }
    setEmailError('');
    setName(initial.name);
    setEmail(initial.email);
  }

  return (
    <form data-testid={testid} onSubmit={submit}>
      <input
        data-testid={`${testid}-name`}
